TEST(MetadataRecordSerdeTest, RegisterBrokerVersionsMatchJavaIncludingNullableTaggedArrays) {
  Uuid dir{};
  dir.back() = 3;
  RegisterBrokerRecord reg;
  reg.broker_id = 2;
  reg.broker_epoch = 12;
  reg.incarnation_id.back() = 7;
  auto& ep = reg.end_points.emplace_back();
  ep.name = "RESP";
  ep.host = "db";
  ep.port = 6379;
  ep.unknown_tags.emplace(8, "3");
  auto& feature = reg.features.emplace_back();
  feature.name = "dragonfly.cluster";
  feature.max_supported_version = 1;
  for (int16_t version = 0; version <= reg.kMaxVersion; ++version) {
    if (version == 1) {
      reg.in_controlled_shutdown = true;
      reg.rack.reset();
    }
    if (version == 2)
      reg.is_migrating_zk_broker = true;
    if (version == 3)
      reg.log_dirs.push_back(dir);
    if (version == 4)
      reg.cordoned_log_dirs.emplace();
    MetadataRecord expected{reg, version};
    auto wire = EncodeMetadataRecord(expected);
    ASSERT_TRUE(wire.ok()) << wire.status();
    EXPECT_EQ(absl::BytesToHexString(*wire), kJavaRecords[version]);
    auto decoded = DecodeMetadataRecord(*wire);
    ASSERT_TRUE(decoded.ok()) << decoded.status();
    EXPECT_EQ(*decoded, expected);
  }
  EXPECT_FALSE(EncodeMetadataRecord({reg, 3}).ok());
}

TEST(MetadataRecordSerdeTest, BrokerChangesTransactionsAndNoOpsMatchJava) {
  for (size_t index = 5; index < size(kJavaRecords); ++index) {
    string bytes;
    ASSERT_TRUE(absl::HexStringToBytes(kJavaRecords[index], &bytes));
    auto record = DecodeMetadataRecord(bytes);
    ASSERT_TRUE(record.ok()) << record.status();
    if (index < 9) {
      const auto& change = get<BrokerRegistrationChangeRecord>(record->message);
      EXPECT_EQ(record->version, index - 5);
      EXPECT_EQ(change.broker_epoch, 12);
      EXPECT_EQ(change.fenced, -1);
      EXPECT_EQ(change.in_controlled_shutdown, index >= 6);
      EXPECT_EQ(change.log_dirs.size(), index >= 7 ? 1u : 0u);
      EXPECT_EQ(change.cordoned_log_dirs.has_value(), index >= 8);
    }
    if (index == 9)
      EXPECT_EQ(get<FeatureLevelRecord>(record->message).feature_level, 33);
    if (index == 10)
      EXPECT_EQ(get<BeginTransactionRecord>(record->message).name, "slots");
    if (index == 12)
      EXPECT_EQ(get<AbortTransactionRecord>(record->message).reason, "stale");
    EXPECT_EQ(EncodeMetadataRecord(*record).value(), bytes);
  }
}

TEST(MetadataRecordSerdeTest, RejectsInvalidHeadersVersionsBodiesAndTrailingBytes) {
  for (const auto* hex : {"", "00", "0f", "0180", "01ffff0300", "0114ffff03", "01ff7f0000",
                          "01180001", "01180100", "0118000000", "01000080", "011780"}) {
    string bytes;
    ASSERT_TRUE(absl::HexStringToBytes(hex, &bytes));
    EXPECT_FALSE(DecodeMetadataRecord(bytes).ok()) << hex;
  }
}

